import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/M-S-Search.C3B92iCp.js";import{_ as i}from"./chunks/CrystalBall.BdqnOTQQ.js";import{_ as s,o,c as r,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"use/settings.md","filePath":"use/settings.md"}'),d={name:"use/settings.md"};function p(c,a,l,h,m,u){return o(),r("div",null,[...a[0]||(a[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings</p></div><p>There are many settings in xDrip, if you can&#39;t find what you&#39;re looking for, use the search lens top right and enter the keyword you&#39;re looking for.</p><img src="'+e+'" style="zoom:75%;"><br><h3 id="glucose-units" tabindex="-1">Glucose Units <a class="header-anchor" href="#glucose-units" aria-label="Permalink to &quot;Glucose Units&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Glucose Units</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_ruler_grey600_48dp.png" style="width:5%;"> mmol/l or mg/dl high and low</p></div><p>In this menu you can select the units used by xDrip (mg/dl or mmol/l) and set high and low targets.</p><div class="admonition xdripitem"><p class="admonition-title">Glucose Units</p><p> mg/dl or mmol/l</p></div><p>These two targets will decide when the graph BG dots change color above or below target.</p><div class="admonition xdripitem"><p class="admonition-title">High Value</p><p> 170</p></div><div class="admonition xdripitem"><p class="admonition-title">Low Value</p><p> 70</p></div><h3 id="alarms-and-alerts" tabindex="-1"><a href="./alarms.html">Alarms and Alerts</a> <a class="header-anchor" href="#alarms-and-alerts" aria-label="Permalink to &quot;[Alarms and Alerts](./alarms)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Alarms and Alerts</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_add_alert_grey600_48dp.png" style="width:5%;"> Glucose, Calibration and Other alerts</p></div><h3 id="hardware-data-source" tabindex="-1"><a href="./../install/datasource.html">Hardware Data Source</a> <a class="header-anchor" href="#hardware-data-source" aria-label="Permalink to &quot;[Hardware Data Source](../install/datasource)&quot;">​</a></h3><p>These settings depend on the data source selected.</p><div class="admonition xdrip"><p class="admonition-title">Hardware Data Source</p></div><h3 id="nfc-scan-features" tabindex="-1"><a href="./NFC.html">NFC Scan features</a> <a class="header-anchor" href="#nfc-scan-features" aria-label="Permalink to &quot;[NFC Scan features](./NFC)&quot;">​</a></h3><p>This menu is only visible if you choose a Libre Bluetooth data source in the Hardware Data Source. If you need to access it to change smoothing parameters for Libre sensors, temporarily modify the data source.</p><div class="admonition xdrip"><p class="admonition-title">NFC Scan features</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_nfc_grey600_48dp.png" style="width:5%;"> Options for scanning NFC based sensors with the phone handset</p></div><h3 id="auto-configure" tabindex="-1"><a href="./copysettings.html#auto-configure">Auto configure</a> <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;[Auto configure](./copysettings#auto-configure)&quot;">​</a></h3><p>Auto configure will help you copy settings between two xDrip apps installed on different phones. This and <a href="./copysettings.html#show-settings-qr-code">Show Settings QR Code</a> both live under the &quot;Copying Settings&quot; screen.</p><div class="admonition xdrip"><p class="admonition-title">Auto configure</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Auto configure using a barcode.</p></div><h3 id="cloud-upload" tabindex="-1"><a href="./cloud.html">Cloud Upload</a> <a class="header-anchor" href="#cloud-upload" aria-label="Permalink to &quot;[Cloud Upload](./cloud)&quot;">​</a></h3><p>Cloud upload is used to configure various sharing and data upload features.</p><div class="admonition xdrip"><p class="admonition-title">Cloud Upload</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Options for Nightscout, MongoDB or Dexcom Share uploading</p></div><h3 id="glucose-meters" tabindex="-1"><a href="./glucometer.html">Glucose Meters</a> <a class="header-anchor" href="#glucose-meters" aria-label="Permalink to &quot;[Glucose Meters](./glucometer)&quot;">​</a></h3><p>You can connect compatible glucose meters to xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Glucose Meters</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_touch_app_grey600_48dp.png" style="width:5%;"> Options for wireless glucose meters</p></div><h3 id="smart-watch-features" tabindex="-1"><a href="./../smartwatch/smartwatch.html">Smart Watch Features</a> <a class="header-anchor" href="#smart-watch-features" aria-label="Permalink to &quot;[Smart Watch Features](../smartwatch/smartwatch)&quot;">​</a></h3><p>Various smartwatches can receive data and display them from xDrip, some can even act as a standalone collector.</p><div class="admonition xdrip"><p class="admonition-title">Smart Watch Features</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options for different Watches</p></div><h3 id="speak-readings" tabindex="-1"><a href="./speak.html">Speak Readings</a> <a class="header-anchor" href="#speak-readings" aria-label="Permalink to &quot;[Speak Readings](./speak)&quot;">​</a></h3><p>xDrip can use the phone to speak values and alerts.</p><div class="admonition xdrip"><p class="admonition-title">Speak Readings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_speak_reading_grey600_48dp.png" style="width:5%;"> If the phone has text-to-speech capabilities it will speak each new reading</p></div><h3 id="inter-app-settings" tabindex="-1"><a href="./interapp.html">Inter-app settings</a> <a class="header-anchor" href="#inter-app-settings" aria-label="Permalink to &quot;[Inter-app settings](./interapp)&quot;">​</a></h3><p>xDrip can accept or send data to other apps, and act as a local web server.</p><div class="admonition xdrip"><p class="admonition-title">Inter-app settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_open_in_app_grey600_48dp.png" style="width:5%;"> For interacting with other compatible apps</p></div><h3 id="less-common-settings" tabindex="-1"><a href="./lesscommon.html">Less common settings</a> <a class="header-anchor" href="#less-common-settings" aria-label="Permalink to &quot;[Less common settings](./lesscommon)&quot;">​</a></h3><p>More settings are available in this menu.</p><div class="admonition xdrip"><p class="admonition-title">Less common settings</p><p> Debug and other misc. options</p></div><h3 id="display" tabindex="-1"><a href="./display.html">Display</a> <a class="header-anchor" href="#display" aria-label="Permalink to &quot;[Display](./display)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Display</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_chart_areaspline_grey600_48dp.png" style="width:5%;"> Display customizations</p></div><h3 id="predictive-simulations" tabindex="-1"><a href="./predictions.html">Predictive simulations</a> <a class="header-anchor" href="#predictive-simulations" aria-label="Permalink to &quot;[Predictive simulations](./predictions)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Predictive simulations</p><p> <img src="'+i+'" style="width:5%;"> Insulin, Carb ratios etc. for models</p></div><h3 id="xdrip-sync" tabindex="-1"><a href="./sync.html">xDrip sync</a> <a class="header-anchor" href="#xdrip-sync" aria-label="Permalink to &quot;[xDrip sync](./sync)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">xDrip sync</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> Settings for syncing between handsets</p></div><h3 id="motion-tracking" tabindex="-1"><a href="./motion.html">Motion tracking</a> <a class="header-anchor" href="#motion-tracking" aria-label="Permalink to &quot;[Motion tracking](./motion)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Motion tracking</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_car_connected_grey600_48dp.png" style="width:5%;"> Movement detection and vehicle mode</p></div><h3 id="update-settings" tabindex="-1"><a href="./update.html">Update settings</a> <a class="header-anchor" href="#update-settings" aria-label="Permalink to &quot;[Update settings](./update)&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title">Update settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_briefcase_download_grey600_48dp.png" style="width:5%;"> Automatic Updates, crash reports and Feedback to Developer</p></div><h3 id="show-settings-qr-code" tabindex="-1"><a href="./copysettings.html#show-settings-qr-code">Show Settings QR Code</a> <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;[Show Settings QR Code](./copysettings#show-settings-qr-code)&quot;">​</a></h3><p>This feature is used to transfer settings between phones.</p><div class="admonition xdrip"><p class="admonition-title">Show Settings QR Code</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"></p></div><h3 id="load-save-settings" tabindex="-1"><a href="./loadsavesettings.html">Load / Save Settings</a> <a class="header-anchor" href="#load-save-settings" aria-label="Permalink to &quot;[Load / Save Settings](./loadsavesettings)&quot;">​</a></h3><p>You can back up and retrieve your xDrip settings.</p><div class="admonition xdrip"><p class="admonition-title">Load / Save Settings</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_content_save_grey600_48dp.png" style="width:5%;"></p></div><h3 id="insulin-pens" tabindex="-1"><a href="./pens.html">Insulin Pens</a> <a class="header-anchor" href="#insulin-pens" aria-label="Permalink to &quot;[Insulin Pens](./pens)&quot;">​</a></h3><p>Some insulin pens can be used with xDrip.</p><div class="admonition xdrip"><p class="admonition-title">Insulin Pens</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_mode_edit_grey_600_48dp.png" style="width:5%;"></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',61)])])}const _=s(d,[["render",p]]);export{x as __pageData,_ as default};
